function bindSongFields(){const s=state.song;['title','composer','artist','lyricist','key','sourceUrl','rightsNote','lyrics'].forEach(k=>$('#'+k).oninput=e=>{s[k]=e.target.value;if(k==='title')$('#crumb').textContent=s.title});$('#bpm').oninput=e=>s.bpm=Math.max(20,Math.min(300,+e.target.value||92));$('#partName').oninput=e=>state.song.parts[state.partIndex].name=e.target.value}
