function editNote(i){const p=state.song.parts[state.partIndex],n=p.notes[i];if(!n)return;const v=prompt('Edit: bar,beat,duration,MIDI note,lyric\nExample: 2,1,0.5,64,la',`${n.bar},${n.beat},${n.duration},${n.midi},${n.lyric||''}`);if(v===null)return;const a=v.split(',');n.bar=Math.max(1,+a[0]||1);n.beat=Math.max(1,Math.min(4,+a[1]||1));n.duration=Math.max(.125,+a[2]||1);n.midi=Math.max(0,Math.min(127,+a[3]||60));n.lyric=(a.slice(4).join(',')||'').trim();renderEditor()}
